def solve(inputs: dict) -> float:
    rems = inputs['remainders']
    mods = inputs['moduli']

    # Extended GCD
    def egcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = egcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    # Modular inverse
    def modinv(a, m):
        gcd, x, _ = egcd(a % m, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    # CRT for two congruences
    def crt_two(r1, m1, r2, m2):
        gcd, p, q = egcd(m1, m2)
        if (r2 - r1) % gcd != 0:
            return None
        lcm = m1 * m2 // gcd
        x = (r1 + m1 * p * ((r2 - r1) // gcd)) % lcm
        return x, lcm

    # Solve iteratively
    r = rems[0]
    m = mods[0]

    for i in range(1, len(rems)):
        result = crt_two(r, m, rems[i], mods[i])
        if result is None:
            return -1
        r, m = result

    return float(r)
